from pathlib import Path
p=Path('public/bank/app.js');s=p.read_text(encoding='utf-8')
extra=r'''
function taskList(p){return `<div class="plan-task-list">${(p.tasks||[]).map((t,i)=>`<button class="plan-task ${t.done?'done':''}" data-action="taskToggle" data-plan="${p.id}" data-task="${t.id}" aria-pressed="${t.done}"><span>${t.done?'✓':i+1}</span><strong>${esc(t.label)}</strong><small>${t.done?'已完成':'待办理'}</small></button>`).join('')||'<p>这个旧计划没有分步清单，可创建新活动添加。</p>'}<p>需要支付时使用下方预算付款入口，每次均需独立转账密码。AA 分摊可前往转账与收款。</p>${btn('前往转账与 AA 分摊','nav','','data-view="transfer"')}</div>`;}
function inbox(){const list=(model.notifications||[]).filter(n=>inboxFilter!=='unread'||!n.read);return title('消息与待办','把接下来要做的事，放在一起。',btn('全部标为已读','readNotice','','data-id="all"'))+`<div class="tabs"><button data-action="inboxFilter" data-filter="all" class="${inboxFilter==='all'?'selected':''}">全部消息</button><button data-action="inboxFilter" data-filter="unread" class="${inboxFilter==='unread'?'selected':''}">未读 ${(model.notifications||[]).filter(n=>!n.read).length}</button></div><p class="notice">站内提醒依据模拟时钟生成。活动到期不自动付款；未接入短信、邮件和浏览器外推送。</p><section class="inbox-list">${list.map(n=>`<article class="notice-item ${n.read?'read':''}"><div><span class="tag">${esc(n.kind)}</span><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p><small>${stamp(n.at)} · ${n.read?'已读':'未读'}</small></div><div>${btn('查看并办理','noticeOpen','',`data-id="${esc(n.id)}" data-view="${n.view}"`)}${!n.read?btn('标为已读','readNotice','',`data-id="${esc(n.id)}"`):''}</div></article>`).join('')||'<p class="empty">当前没有需要处理的消息。</p>'}</section>`;}
function receiptText(id,kind){const s=model.state;if(kind==='transaction'){const t=s.transactions.find(x=>x.id===id);if(!t)return '';return ['个人银行 · 模拟交易回执','仅供比赛演示，不具有真实银行凭证效力','交易编号：'+t.id,'交易时间：'+stamp(t.at),'交易对象：'+t.merchant,'类型：'+t.category,'状态：'+t.status,'金额：CNY '+money(Math.abs(t.amount)),'方向：'+(t.amount<0?'支出':'收入'),'手续费：CNY '+money(t.fee||0),'渠道：'+(t.channel||'示例账本'),t.recipient?'收款银行：'+(t.recipient.bank||'模拟联系人')+' / 尾号 '+(t.recipient.account?.slice(-4)||t.recipient.phone):'', '备注：'+(t.note||'无')].filter(Boolean).join('\n');}const r=s.receipts.find(x=>x.id===id);if(!r)return '';const plan=s.plans.find(p=>p.id===r.planId);return ['个人银行 · 模拟操作回执','仅供比赛演示，不具有真实银行凭证效力','回执编号：'+r.id,'操作：'+r.title,'时间：'+stamp(r.at),'状态：'+(plan?status(plan.status):r.status||'已完成'),...(r.lines||[]),...(plan?['执行时间：'+stamp(plan.at),...plan.steps]:[])].join('\n');}
function downloadReceipt(id,kind){const text=receiptText(id,kind);if(!text){toast('回执不存在');return;}const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='模拟回执-'+id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function receipts(){const s=model.state;return title('交易回执','每次确认都有记录，每笔资金都有去向。')+`<section><h2>操作与预约回执</h2>${s.receipts.map(r=>{const plan=s.plans.find(p=>p.id===r.planId);return `<details class="receipt-document"><summary><span><strong>${esc(r.title)}</strong><small>${stamp(r.at)}</small></span><span>${plan?status(plan.status):'已完成'}</span></summary><pre>${esc(receiptText(r.id,'operation'))}</pre>${btn('下载模拟回执','receiptDownload','',`data-id="${r.id}" data-kind="operation"`)}${plan&&['scheduled','paused','ready'].includes(plan.status)?btn('取消预约并释放资金','cancelPlan','',`data-id="${plan.id}"`):''}</details>`;}).join('')||'<p>完成一笔操作后，这里会显示确认回执。</p>'}</section><section class="section"><h2>入账交易</h2>${s.transactions.map(t=>`<details class="receipt-document"><summary><span><strong>${esc(t.merchant)}</strong><small>${stamp(t.at)} · ${esc(t.category)}</small></span><b>${t.amount<0?'−':'+'} ¥${money(Math.abs(t.amount))}</b></summary><pre>${esc(receiptText(t.id,'transaction'))}</pre>${btn('下载交易回执','receiptDownload','',`data-id="${t.id}" data-kind="transaction"`)}</details>`).join('')}</section>`;}
const demoScenarios=[['travel','智能转账','transfer','选择收款人或直接填写模拟卡号 → 核对金额 → 输入转账密码 → 查看回执。也可展示预约与 AA 分摊。'],['bills','账单分析','bills','切换月度与年度 → 筛选消费分类 → 展开待核实交易 → 导出账单。'],['invest','适当性与理财','invest','完成 10 项问卷 → 比较风险匹配产品 → 模拟申购 → 查看持仓与赎回限制。'],['cards','银行卡管理','cards','展示多卡与卡面定制 → 调整限额或锁卡 → 验证交易限制。'],['subscriptions','订阅与代扣','subscriptions','查看预计支出 → 开启提醒 → 取消或恢复授权 → 在消息中心检查提醒。'],['birthday','多步骤联动','plans','载入零预算演示计划 → 勾选步骤 → 编辑预算与日期 → 确认模拟付款 → 完成并释放剩余预留。']];
function demo(){return title('比赛演示','六个场景，一条可核对的演示路径。')+`<p class="notice">“载入演示”不会清空现有账户或扣款；联动场景添加零预算示例。所有交易仍需本人确认。正式六条要求的最终验收以比赛原文为准。</p><div class="demo-grid">${demoScenarios.map(([id,name,view,steps],i)=>`<article><span class="demo-number">${String(i+1).padStart(2,'0')}</span><h2>${name}</h2><p>${steps}</p>${btn('载入并开始演示','demoSeed','',`data-scenario="${id}" data-view="${view}"`)}</article>`).join('')}</div><section class="section"><h2>演示边界与队友对接</h2><p>已实现：持久模拟账本、独立密码、工具确认、风控校验、回执、消息与活动步骤。</p><p>待对接：真实银行与商户接口、正式身份核验、实时行情、大模型多轮规划、后台定时任务和外部消息投递。当前助手仍使用规则解析。</p><p>时间演示：在联动计划页展开“演示时钟”，手动推进日期以检查到期状态。账户数据不会因登录会话到期被清除。</p></section>`;}
'''
s=s.replace('function render(){',extra+'\nfunction render(){')
s=s.replace('profile:\'密码登录转账安全设置称呼个人中心\'',"profile:'密码登录转账安全设置称呼个人中心',inbox:'消息待办提醒通知',receipts:'回执凭证预约状态',demo:'比赛演示六场景'")
s=s.replace('每位访客使用独立 Cookie 会话，七天后过期；清除 Cookie 后无法找回旧演示。','持久账号支持跨设备登录；会话到期不删除账户，旧浏览器账户需要迁移。')
